using UnityEngine;using Alterverse.Characters;using Alterverse.Combat;
namespace Alterverse.AI
{
[RequireComponent(typeof(TeamMember))]public sealed class BotTargetSensor:MonoBehaviour
{
[SerializeField]private float fallbackScanRadius=10f,scanInterval=.22f;private TeamMember teamMember;private Health selfHealth,currentTarget;private HeroCombatProfile profile;private float nextScanTime;public Health CurrentTarget=>currentTarget;
private void Awake(){teamMember=GetComponent<TeamMember>();selfHealth=GetComponent<Health>();profile=GetComponent<HeroCombatProfile>();}public void ClearTarget(){currentTarget=null;nextScanTime=0;}
private void Update(){if(Time.timeScale<=0f)return;if(selfHealth!=null&&selfHealth.IsDead){ClearTarget();return;}if(Time.time<nextScanTime)return;nextScanTime=Time.time+Mathf.Max(.12f,scanInterval);Scan();}
private void Scan(){currentTarget=null;float bestScore=float.MaxValue;float scanRadius=profile!=null?Mathf.Max(fallbackScanRadius,profile.AttackRange+4f):fallbackScanRadius;float maxSqr=scanRadius*scanRadius;foreach(Health candidateHealth in FindObjectsByType<Health>()){if(candidateHealth==null||candidateHealth==selfHealth||candidateHealth.IsDead)continue;bool enemy=false;float priority=1f;TeamMember candidateTeam=candidateHealth.GetComponent<TeamMember>();if(candidateTeam!=null&&teamMember!=null){enemy=teamMember.IsEnemy(candidateTeam);priority=candidateHealth.GetComponent<HeroIdentity>()!=null?.72f:1f;}else{LaneMinion minion=candidateHealth.GetComponent<LaneMinion>();if(minion!=null){enemy=minion.Team!=teamMember.Team;priority=.9f;}else{LaneTower tower=candidateHealth.GetComponent<LaneTower>();if(tower!=null){enemy=tower.Team!=teamMember.Team;priority=1.15f;}}}if(!enemy)continue;Vector3 delta=candidateHealth.transform.position-transform.position;delta.y=0;float sqr=delta.sqrMagnitude;if(sqr>maxSqr)continue;float score=sqr*Mathf.Lerp(.7f,1f,candidateHealth.Normalized)*priority;if(score<bestScore){bestScore=score;currentTarget=candidateHealth;}}}
}
}